window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c857c6abf0ae011f"]={"versions": [{"id": "FIG-c857c6abf0ae011f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Metamodell-Instanzdiagramm zur Spezifikation der AUTOSAR-XML-Serialisierungsregeln (AUTOSAR Model Persistence Rules for XML). Dargestellt ist die metamodellierte Repräsentation einer gerichteten Kompositionsbeziehung (Aggregation = composite) zwischen zwei UML-Klassen im Vergleich zur abstrakten Syntax des UML-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Repräsentationsebenen:</p>\n<ul class=\"fig-list\">\n<li><strong>Obere Ebene (UML-Benutzermodell / Konkrete Syntax):</strong></li>\n<li>Klasse <code>A</code>: Aggregierende Quellklasse (Ganzes).</li>\n<li>Klasse <code>C</code>: Aggregierte Zielklasse (Teil).</li>\n<li>Beziehung: Kompositionsaggregation (gekennzeichnet durch eine ausgefüllte Raute auf Seiten von <code>A</code>), navigierbar von <code>A</code> nach <code>C</code> mit Rollenbezeichnung <code>+theC</code> und Kardinalität <code>0..*</code>.</li>\n<li><strong>Untere Ebene (Metamodell-Instanzen / Abstrakte Syntax):</strong></li>\n<li>Instanz <code>«metaclass» :Class</code> mit Attribut <code>name = A</code>.</li>\n<li>Instanz <code>«metaclass» :Class</code> mit Attribut <code>name = C</code>.</li>\n<li>Instanz <code>«metaclass» :Association</code> mit Attribut <code>name = </code> (anonym/leer).</li>\n<li>Quellseitige Instanz <code>«metaclass» :Property</code> mit Attributwerten <code>aggregation = none</code>, <code>upper = 1</code>, <code>lower = 0</code>, <code>name = </code> (leer). Referenzen: <code>+type</code> auf <code>:Class</code> (<code>A</code>), per Komposition (<code>+ownedEnd</code>) und Association (<code>+memberEnd</code>) mit <code>:Association</code> verbunden.</li>\n<li>Zielseitige Instanz <code>«metaclass» :Property</code> mit Attributwerten <code>aggregation = composite</code>, <code>upper = unbounded</code>, <code>lower = 0</code>, <code>name = theC</code>. Referenzen: <code>+type</code> auf <code>:Class</code> (<code>C</code>), Verknüpfung <code>+memberEnd</code> von <code>:Association</code> sowie Kompositionseigenschaft <code>+ownedAttribute</code> ausgehend von <code>:Class</code> (<code>A</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturdiagramm ohne zeitlichen oder sequenziellen Ablauf. Es beschreibt die strukturelle Zuordnung der UML-Metaklassen und -Properties zur Abbildung einer Kompositionsassoziation. Die navigierbare Endrolle <code>theC</code> wird als <code>ownedAttribute</code> der besitzenden Klasse <code>A</code> mit <code>aggregation = composite</code> und unbeschränkter Obergrenze modelliert, während die Gegenrolle namenlos bleibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der UML-Metamodell-Struktur für AUTOSAR-Metamodelle zur Ableitung der XML-Schema- (XSD) und Serialisierungsregeln:</p>\n<ul class=\"fig-list\">\n<li>Eine Kompositionsassoziation mit Kardinalität <code>0..*</code> und Rollenname <code>theC</code> an Zielklasse <code>C</code> erfordert im Metamodell eine Metaklasse <code>:Property</code> als <code>ownedAttribute</code> von Metaklasse <code>A</code>.</li>\n<li>Die zielseitige <code>:Property</code> muss normativ die Werte <code>aggregation = composite</code>, <code>lower = 0</code>, <code>upper = unbounded</code> und <code>name = theC</code> tragen und referenziert per <code>+type</code> die Metaklasse <code>C</code>.</li>\n<li>Die assoziierte Gegenrolle besitzt <code>aggregation = none</code>, <code>lower = 0</code>, <code>upper = 1</code> und ist über <code>ownedEnd</code> an die Assoziation gebunden.</li>\n<li>Modellierungs- und Generierungswerkzeuge müssen diese Metamodell-Konfiguration zur Erzeugung konsistenter XML-Strukturen und Schachtelungen einhalten.</li>\n</ul>"}, {"id": "FIG-29dbe4756f26fcea", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Metamodell-Instanzdiagramm zur Spezifikation der AUTOSAR-XML-Serialisierungsregeln (AUTOSAR Model Persistence Rules for XML). Dargestellt ist die metamodellierte Repräsentation einer gerichteten Kompositionsbeziehung (Aggregation = composite) zwischen zwei UML-Klassen im Vergleich zur abstrakten Syntax des UML-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Repräsentationsebenen:</p>\n<ul class=\"fig-list\">\n<li><strong>Obere Ebene (UML-Benutzermodell / Konkrete Syntax):</strong></li>\n<li>Klasse <code>A</code>: Aggregierende Quellklasse (Ganzes).</li>\n<li>Klasse <code>C</code>: Aggregierte Zielklasse (Teil).</li>\n<li>Beziehung: Kompositionsaggregation (gekennzeichnet durch eine ausgefüllte Raute auf Seiten von <code>A</code>), navigierbar von <code>A</code> nach <code>C</code> mit Rollenbezeichnung <code>+theC</code> und Kardinalität <code>0..*</code>.</li>\n<li><strong>Untere Ebene (Metamodell-Instanzen / Abstrakte Syntax):</strong></li>\n<li>Instanz <code>«metaclass» :Class</code> mit Attribut <code>name = A</code>.</li>\n<li>Instanz <code>«metaclass» :Class</code> mit Attribut <code>name = C</code>.</li>\n<li>Instanz <code>«metaclass» :Association</code> mit Attribut <code>name = </code> (anonym/leer).</li>\n<li>Quellseitige Instanz <code>«metaclass» :Property</code> mit Attributwerten <code>aggregation = none</code>, <code>upper = 1</code>, <code>lower = 0</code>, <code>name = </code> (leer). Referenzen: <code>+type</code> auf <code>:Class</code> (<code>A</code>), per Komposition (<code>+ownedEnd</code>) und Association (<code>+memberEnd</code>) mit <code>:Association</code> verbunden.</li>\n<li>Zielseitige Instanz <code>«metaclass» :Property</code> mit Attributwerten <code>aggregation = composite</code>, <code>upper = unbounded</code>, <code>lower = 0</code>, <code>name = theC</code>. Referenzen: <code>+type</code> auf <code>:Class</code> (<code>C</code>), Verknüpfung <code>+memberEnd</code> von <code>:Association</code> sowie Kompositionseigenschaft <code>+ownedAttribute</code> ausgehend von <code>:Class</code> (<code>A</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturdiagramm ohne zeitlichen oder sequenziellen Ablauf. Es beschreibt die strukturelle Zuordnung der UML-Metaklassen und -Properties zur Abbildung einer Kompositionsassoziation. Die navigierbare Endrolle <code>theC</code> wird als <code>ownedAttribute</code> der besitzenden Klasse <code>A</code> mit <code>aggregation = composite</code> und unbeschränkter Obergrenze modelliert, während die Gegenrolle namenlos bleibt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der UML-Metamodell-Struktur für AUTOSAR-Metamodelle zur Ableitung der XML-Schema- (XSD) und Serialisierungsregeln:</p>\n<ul class=\"fig-list\">\n<li>Eine Kompositionsassoziation mit Kardinalität <code>0..*</code> und Rollenname <code>theC</code> an Zielklasse <code>C</code> erfordert im Metamodell eine Metaklasse <code>:Property</code> als <code>ownedAttribute</code> von Metaklasse <code>A</code>.</li>\n<li>Die zielseitige <code>:Property</code> muss normativ die Werte <code>aggregation = composite</code>, <code>lower = 0</code>, <code>upper = unbounded</code> und <code>name = theC</code> tragen und referenziert per <code>+type</code> die Metaklasse <code>C</code>.</li>\n<li>Die assoziierte Gegenrolle besitzt <code>aggregation = none</code>, <code>lower = 0</code>, <code>upper = 1</code> und ist über <code>ownedEnd</code> an die Assoziation gebunden.</li>\n<li>Modellierungs- und Generierungswerkzeuge müssen diese Metamodell-Konfiguration zur Erzeugung konsistenter XML-Strukturen und Schachtelungen einhalten.</li>\n</ul>"}], "trans": [{"from": "FIG-c857c6abf0ae011f", "to": "FIG-29dbe4756f26fcea", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
